'use strict';

// MODULES //

var isCollection = require( '@stdlib/assert/is-collection' );
var isInteger = require( '@stdlib/math/base/assert/is-integer' );
var format = require( '@stdlib/string/format' );
var floor = require( '@stdlib/math/base/special/floor' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var copyWithinTypedArrays = require( './typed_arrays.js' );


// MAIN //

/**
* Copies a sequence of elements within a collection to another location in the same collection.
*
* @param {Collection} collection - input collection
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=collection.length] - source end index
* @throws {TypeError} first argument must be a collection
* @returns {Collection} modified input collection
*
* @example
* var arr = [ 1, 2, 3, 4, 5 ];
* var out = copyWithin( arr, 0, 3 );
* // returns [ 4, 5, 3, 4, 5 ]
*
* @example
* var arr = [ 1, 2, 3, 4, 5 ];
* var out = copyWithin( arr, 0, 3, 4 );
* // returns [ 4, 2, 3, 4, 5 ]
*
* @example
* var arr = [ 1, 2, 3, 4, 5 ];
* var out = copyWithin( arr, -2, -3, -1 );
* // returns [ 1, 2, 3, 3, 4 ]
*/
function copyWithin( collection, target, start, end ) {
	var result;
	var len;
	var t;
	var s;
	var e;
	var i;
	var n;

	if ( !isCollection( collection ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a collection. Value: `%s`.', collection ) );
	}

	// If the collection has a built-in copyWithin method, use it:
	if ( typeof collection.copyWithin === 'function' ) {
		if ( arguments.length === 2 ) {
			return collection.copyWithin( target );
		}
		if ( arguments.length === 3 ) {
			return collection.copyWithin( target, start );
		}
		return collection.copyWithin( target, start, end );
	}

	// Use optimized implementations for typed arrays:
	result = copyWithinTypedArrays( collection, target, start, end );
	if ( result !== null ) {
		return result;
	}

	len = collection.length;

	// Convert target to integer and handle negative indices:
	if ( isInteger( target ) ) {
		t = target;
	} else {
		t = floor( target );
	}
	if ( t < 0 ) {
		t = max( len + t, 0 );
	} else {
		t = min( t, len );
	}

	// Convert start to integer and handle negative indices:
	if ( start === void 0 ) {
		s = 0;
	} else if ( isInteger( start ) ) {
		s = start;
	} else {
		s = floor( start );
	}
	if ( s < 0 ) {
		s = max( len + s, 0 );
	} else {
		s = min( s, len );
	}

	// Convert end to integer and handle negative indices:
	if ( end === void 0 ) {
		e = len;
	} else if ( isInteger( end ) ) {
		e = end;
	} else {
		e = floor( end );
	}
	if ( e < 0 ) {
		e = max( len + e, 0 );
	} else {
		e = min( e, len );
	}

	// Calculate the number of elements to copy:
	n = min( e - s, len - t );

	// Handle case where copying would overlap:
	if ( t < s ) {
		// Copy from left to right:
		for ( i = 0; i < n; i++ ) {
			if ( s + i in collection ) {
				collection[ t + i ] = collection[ s + i ];
			} else {
				delete collection[ t + i ];
			}
		}
	} else if ( t > s ) {
		// Copy from right to left to avoid overwriting elements:
		for ( i = n - 1; i >= 0; i-- ) {
			if ( s + i in collection ) {
				collection[ t + i ] = collection[ s + i ];
			} else {
				delete collection[ t + i ];
			}
		}
	}

	return collection;
}


// EXPORTS //

module.exports = copyWithin;
